      4'd8: b2[3] <= cl_68;
      4'd9: b2[3] <= cl_69;
      default: b2[3] <= '0;
    endcase
    unique case (b1[4])
      4'd0: b2[4] <= cl_21;
      4'd1: b2[4] <= cl_36;
      4'd2: b2[4] <= cl_41;
      4'd3: b2[4] <= cl_49;
      4'd4: b2[4] <= cl_68;
      4'd5: b2[4] <= cl_69;
      default: b2[4] <= '0;
    endcase
    unique case (b1[5])
      4'd0: b2[5] <= cl_22;
      4'd1: b2[5] <= cl_42;
      4'd2: b2[5] <= cl_50;
      4'd3: b2[5] <= cl_69;
      default: b2[5] <= '0;
    endcase
    unique case (b1[6])
      4'd0: b2[6] <= cl_23;
      4'd1: b2[6] <= cl_43;
      4'd2: b2[6] <= cl_51;
      default: b2[6] <= '0;
    endcase
    unique case (b1[7])
      4'd0: b2[7] <= cl_24;
      4'd1: b2[7] <= cl_44;
      4'd2: b2[7] <= cl_52;
      default: b2[7] <= '0;
    endcase
    lv2 <= lv1; t2 <= t1; g2 <= g1; kind2 <= kind1;
    for (int l = 0; l < S; ++l)
      for (int x = 0; x < 3; ++x) begin
        logic signed [18:0] d;
        d = 19'(signed'(a2[x])) - 19'(signed'(b2[l][x]));
        sq3[l][x] <= 38'(d * d);
      end
    lv3 <= lv2; t3 <= t2; g3 <= g2; kind3 <= kind2;
    hit4 <= hit3; g4 <= g3; kind4 <= kind3; lv4 <= lv3;
  end
  always_comb
    for (int l = 0; l < S; ++l)
      hit3[l] = lv3[l] && (D2W'(sq3[l][0]) + D2W'(sq3[l][1]) + D2W'(sq3[l][2]) <= D2W'(t3[l]));
  assign in_hit = v4 && kind4 == K_IN && (|hit4);
  assign pipe_busy = v1 || v2 || v3 || v4;

  always_ff @(posedge clk) begin
    if (!rst_n) begin
      state <= S_IDLE; busy <= 1'b0; done <= 1'b0; collide <= 1'b0; pairs <= '0;
      v1 <= 1'b0; v2 <= 1'b0; v3 <= 1'b0; v4 <= 1'b0;
    end else begin
      done <= 1'b0;
      v1 <= issue; v2 <= v1; v3 <= v2; v4 <= v3;
      if (v4 && kind4 == K_OUT)
        for (int l = 0; l < S; ++l) if (hit4[l]) hitm[g4[l][GW-1:0]] <= 1'b1;
      if (v4 && kind4 == K_FIL)                        // no row is taken while filter results land (S_WAIT2)
        for (int l = 0; l < S; ++l) if (hit4[l]) rowm[g4[l][RW-1:0]] <= 1'b1;
      if (done) busy <= 1'b0;
      // entries of the last pose still in flight land during S_OUT (none of this pose can be at stage 4 yet)
      if (v4 && state != S_IDLE && state != S_OUT) pairs <= pairs + 10'($countones(lv4));   // golden count on collision-free poses
      unique case (state)
        S_IDLE: if (start && !busy) begin
          busy <= 1'b1; collide <= 1'b0; hitm <= '0; rowm <= '0; e <= '0; pairs <= '0; state <= S_OUT;
          cl_0 <= c[0]; cl_1 <= c[1]; cl_2 <= c[2]; cl_3 <= c[3]; cl_4 <= c[4]; cl_5 <= c[5]; cl_6 <= c[6]; cl_7 <= c[7]; cl_8 <= c[8]; cl_17 <= c[17]; cl_18 <= c[18]; cl_19 <= c[19]; cl_20 <= c[20]; cl_21 <= c[21]; cl_22 <= c[22]; cl_23 <= c[23]; cl_24 <= c[24]; cl_25 <= c[25]; cl_26 <= c[26]; cl_27 <= c[27]; cl_28 <= c[28]; cl_29 <= c[29]; cl_30 <= c[30]; cl_31 <= c[31]; cl_32 <= c[32]; cl_33 <= c[33]; cl_34 <= c[34]; cl_35 <= c[35]; cl_36 <= c[36]; cl_37 <= c[37]; cl_38 <= c[38]; cl_39 <= c[39]; cl_40 <= c[40]; cl_41 <= c[41]; cl_42 <= c[42]; cl_43 <= c[43]; cl_44 <= c[44]; cl_45 <= c[45]; cl_46 <= c[46]; cl_47 <= c[47]; cl_48 <= c[48]; cl_49 <= c[49]; cl_50 <= c[50]; cl_51 <= c[51]; cl_52 <= c[52]; cl_53 <= c[53]; cl_54 <= c[54]; cl_55 <= c[55]; cl_56 <= c[56]; cl_57 <= c[57]; cl_58 <= c[58]; cl_59 <= c[59]; cl_60 <= c[60]; cl_61 <= c[61]; cl_64 <= c[64]; cl_65 <= c[65]; cl_66 <= c[66]; cl_67 <= c[67]; cl_68 <= c[68]; cl_69 <= c[69];
        end
        S_OUT: if (e == 8'd3) begin state <= S_WAIT; drain <= 3'd0; end else e <= e + 1'b1;
        S_WAIT: begin                                    // let the outer results land in hitm
          drain <= drain + 3'd1;
          if (drain == 3'd4) begin
            logic [5:0] ng;
            ng = next_hit(hitm, 0);
            if (ng == (GW+1)'(NG)) begin state <= S_IDLE; done <= 1'b1; end
            else begin g <= ng[4:0]; e <= g_start(ng[4:0]); k <= '0; state <= S_FIL; end
          end
        end
        S_FIL: if (k == g_count(g) - 1) begin            // filter entries of every hit outer pair
          logic [5:0] ng;
          ng = next_hit(hitm, int'(g) + 1);
          if (ng == (GW+1)'(NG)) begin state <= S_WAIT2; drain <= 3'd0; end
          else begin g <= ng[4:0]; e <= g_start(ng[4:0]); k <= '0; end
        end else begin
          e <= e + 1'b1; k <= k + 1'b1;
        end
        S_WAIT2: begin                                   // let the filter results land in rowm
          drain <= drain + 3'd1;
          if (drain == 3'd4) begin
            logic [RW:0] nr;
            nr = next_row(rowm);
            if (nr == (RW+1)'(NR)) begin state <= S_IDLE; done <= 1'b1; end
            else begin row <= nr[RW-1:0]; rowm[nr[RW-1:0]] <= 1'b0; e <= r_start(nr[RW-1:0]); k <= '0; state <= S_IN; end
          end
        end
        S_IN: if (in_hit) begin
          collide <= 1'b1; done <= 1'b1; state <= S_IDLE;
        end else if (k == r_count(row) - 1) begin
          logic [RW:0] nr;
          nr = next_row(rowm);
          if (nr == (RW+1)'(NR)) begin state <= S_DRAIN; drain <= 3'd0; end
          else begin row <= nr[RW-1:0]; rowm[nr[RW-1:0]] <= 1'b0; e <= r_start(nr[RW-1:0]); k <= '0; end
        end else begin
          e <= e + 1'b1; k <= k + 1'b1;
        end
        S_DRAIN: if (in_hit) begin
          collide <= 1'b1; done <= 1'b1; state <= S_IDLE;
        end else begin
          drain <= drain + 3'd1;
          if (!pipe_busy && drain != 3'd0) begin done <= 1'b1; state <= S_IDLE; end
        end
        default: state <= S_IDLE;
      endcase
    end
  end

endmodule
